import pytest
from HumanEval_8 import sum_product

def test_sum_product_empty():
    assert sum_product([]) == (0, 1)

def test_sum_product_positive_numbers():
    assert sum_product([1, 2, 3, 4]) == (10, 24)

def test_sumum_product_negative_numbers():
    assert sum_product([-1, -2, -3, -4]) == (-10, -24)

def test_sum_product_mixed_numbers():
    assert sum_product([1, -2, 3, -4]) == (-2, -24)

def test_sum_product_large_numbers():
    assert sum_product([100, 200, 300, 400]) == (1000, 2400000)

def test_sum_product_single_number():
    assert sum_product([5]) == (5, 5)

import pytest
from HumanEval_7 import filter_by_substring

def test_filter_by_substring_empty():
    assert filter_by_substring([], 'a') == []

def test_filter_by_substring_single_match():
    assert filter_by_substring(['abc'], 'a') == ['abc']

def test_filter_by_substring_multiple_matches():
    assert filterfilter_by_substring(['abc', 'bacd', 'cde', 'array'], 'a') == ['abc', 'bacd', 'array']

def test_filter_by_substring_no_matches():
    assert filter_by_substring(['abc', 'bacd', 'cde'], 'z') == []

def test_filter_by_substring_empty_substring():
    assert filter_by_substring(['abc', 'bacd', 'cde'], '') == ['abc', 'bacd', 'cde']

