import pytest
from HumanEval_51 import remove_vowels

def test_remove_vowels_empty_string():
    assert remove_vowels("") == ""

def test_remove_vowels_lowercase():
    assert remove_vowels("abcdef\nghijklm") == "bcdf\nghjklm"

def test_remove_vowels_uppercase():
    assert remove_vowels('abcdef') == 'bcdf'

def test_remove_vowels_all_vowels():
    assert remove_vowels('aaaaa') == ''

def test_remove_vowels_mix_case():
    assert remove_vowels('aaBAA') == 'B'

def test_remove_vowels_no_vowels():
    assert remove_vowels('zbcd') == 'zbcd'

import pytest
from HumanEval_53 import add

def test_add_positive_numbers():
    assert add(2, 3) == 5

def test_add_negative_numbers():
    assert add(-2, -3) == -5

def test_add_positive_and_negative_numbers():
    assert add(2, -3) == -1

def test_add_zero():
    assert add(2, 0) == 2
    assert add(0, 3) == 3
    assert add(0, 0) == 0

def test_add_large_numbers():
    assert add(1000000, 2000000) == 3000000

def test_add_non_integer_numbers():
    assert add(1.5, 2.5) == pytest.approx(4.0)
